package common

import (
	"bytes"
	"encoding/base64"
	"io"
	"os"
	"strings"
	"testing"

	"filippo.io/age/armor"
)

const ageFixtureProfile = "vless://00000000-0000-0000-0000-000000000001@age.example:443#AGE-node\n"

func readAgeFixture(t *testing.T, name string) []byte {
	t.Helper()
	data, err := os.ReadFile("testdata/" + name)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

// The armored fixtures and disposable identities were generated by Mihomo
// v1.19.31 using "age keygen"/"age keygen-pq" followed by "age encrypt".
// The binary passphrase fixture was generated by the age v1.3.2 CLI with
// "-e -j batchpass" and AGE_PASSPHRASE_WORK_FACTOR=10 to keep tests fast.
func TestDecodeAgeProviderFixtures(t *testing.T) {
	for _, scheme := range []string{"x25519", "pq"} {
		key := string(readAgeFixture(t, "mihomo-"+scheme+".identity"))
		body := readAgeFixture(t, "mihomo-"+scheme+".age")
		got, err := DecodeSubscriptionBody(body, "", "", key)
		if err != nil || string(got) != ageFixtureProfile {
			t.Fatalf("%s: provider fixture did not decode: %v", scheme, err)
		}
	}
	got, err := DecodeSubscriptionBody(readAgeFixture(t, "scrypt.age"), "", "other password", " fixture passphrase ")
	if err != nil || string(got) != ageFixtureProfile {
		t.Fatalf("age passphrase fixture did not decode: %v", err)
	}
}

func TestDecodeLegacyAesUsesSeparatePassword(t *testing.T) {
	// OpenSSL AES-128-CBC with a zero IV and MD5("fixture AES password").
	body := []byte("AAAAAAAAAAAAAAAAAAAAABodT2FMdXB3usm//Yzvh6g=")
	for _, header := range []string{"TrUe", "1"} {
		got, err := DecodeSubscriptionBody(body, header, "fixture AES password", "different AGE passphrase")
		if err != nil || string(got) != "legacy fixture" {
			t.Fatalf("legacy subscription did not decode with header %q: %v", header, err)
		}
	}
}

func TestDecodeSubscriptionRejectsIncompleteAndMismatchedEnvelopes(t *testing.T) {
	armored := readAgeFixture(t, "mihomo-x25519.age")
	key := string(readAgeFixture(t, "mihomo-x25519.identity"))
	binary, err := io.ReadAll(armor.NewReader(bytes.NewReader(armored)))
	if err != nil {
		t.Fatal(err)
	}
	binary[len(binary)-1] ^= 1
	for _, tc := range []struct {
		name, header, credential string
		body                     []byte
	}{
		{"tampered payload", "", key, binary},
		{"missing armor trailer", "", key, armored[:len(armored)-32]},
		{"invalid identity", "", "AGE-SECRET-KEY-1TESTONLY", armored},
		{"wrong identity", "", string(readAgeFixture(t, "mihomo-pq.identity")), armored},
		{"incorrect passphrase", "", "wrong passphrase", readAgeFixture(t, "scrypt.age")},
		{"missing AGE credential despite AES password", "", "", armored},
		{"declared age without an envelope", "AgE", key, []byte(ageFixtureProfile)},
		{"legacy AES with partial block", "true", "", []byte(base64.StdEncoding.EncodeToString(make([]byte, 17)))},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, err := DecodeSubscriptionBody(tc.body, tc.header, "aes-secret", tc.credential)
			if err == nil || got != nil {
				t.Fatal("incomplete or mismatched envelope was accepted")
			}
			if tc.credential != "" && strings.Contains(err.Error(), strings.TrimSpace(tc.credential)) {
				t.Fatal("error exposed the configured credential")
			}
		})
	}
	got, err := DecodeSubscriptionBody([]byte(ageFixtureProfile), "", "", key)
	if err != nil || string(got) != ageFixtureProfile {
		t.Fatal("unencrypted subscriptions must still work with a stored age identity")
	}
}
